        const polarWave = longitude * 3 - hemisphere * time * 0.18;
        eastward[index] += hemisphere * polarEnvelope * (0.06 + 0.018 * Math.cos(polarWave));
        northward[index] += polarEnvelope * Math.cos(latitude) * 0.012 * Math.sin(polarWave);
